/// <summary>
/// Extension class
/// </summary>
[ExtensionOf(tableStr(InventItemSalesSetup))]
Public final class METInventItemSalesSetupTable_Extension
{
}

Method.Source:
    /// <summary>
    /// CoC on update
    /// </summary>
    public void update()
    {
        boolean fieldUpdated = false;

        if(this.isStopped() != this.orig().isStopped())
        {
            fieldUpdated = true;
        }

        next update();

        if(fieldUpdated)
        {
            METPriceChangeEventProduct::metProcessTrackChange(this.InventTable(), this.InventDimId);
        }
    }
